/** Execute the published deterministic32-root plan once. */
import {readFile,writeFile} from 'node:fs/promises';import {createHash} from 'node:crypto';import assert from 'node:assert/strict';import {performance} from 'node:perf_hooks';import {analyzeAction} from '../../src/bot.js';import * as r from '../../src/rules.js';import * as f from '../search-performance-v5/baseline-rules.js';
const source='research/competitive-engine-v1/three-piece-retrograde.json',bytes=await readFile(source),g=JSON.parse(bytes),selected=[],strata=[];assert(g.summary.complete);for(const turn of ['white','black'])for(const location of ['board','bank'])for(const outcome of ['win','loss']){const ids=g.states.flatMap((s,i)=>!s.result&&s.position.turn===turn&&(s.descriptor.loc===16?'bank':'board')===location&&(g.certificates.winner[i]===turn?'win':'loss')===outcome?[i]:[]);const picks=[0,1,2,3].map(k=>ids[Math.floor((k+.5)*ids.length/4)]);assert(ids.length>=4&&new Set(picks).size===4);strata.push({turn,location,outcome,count:ids.length,picks});selected.push(...picks);}
const options={profile:'competitive',depth:20,maxMillis:100,quiescenceDepth:4,quiescenceChecks:true,quiescenceEvasionDepth:2,lateMoveReduction:true,cacheEvaluation:true,cacheQuiescence:false,reduceQuietDrops:false,reducePrincipalVariation:true,rootTiePriority:false,kingEscapeGeometry:false,rootPrincipalVariation:false,forkThreatEvasions:false,exchangeOrdering:false,stagedOrdering:false,reserveThreatEvaluation:false,protectHistoryMoves:false,stopOnProvenWin:false};const rows=[];
for(const index of selected){const s=g.states[index],before=JSON.stringify(s.position),start=performance.now(),search=analyzeAction(s.position,options),elapsed=performance.now()-start;assert.equal(JSON.stringify(s.position),before);const edge=s.edges.find(e=>r.actionKey(e.action)===r.actionKey(search.action));assert(edge);let p=s.position;for(const a of search.pv){assert(f.legalActions(p).some(x=>f.actionKey(x)===f.actionKey(a)));const next=r.applyAction(p,a),fnext=f.applyLegalAction(p,a);assert.equal(r.positionKey(next),f.positionKey(fnext));p=next;}const winner=g.certificates.winner[index],nextWinner=g.certificates.winner[edge.to];rows.push({index,position:s.position,winner,rank:g.certificates.rank[index],search,elapsed,successor:edge.to,successorWinner:nextWinner,successorRank:g.certificates.rank[edge.to],outcomeChanged:winner===s.position.turn&&nextWinner!==winner});}
const controls=[];for(const turn of ['white','black']){const ids=g.states.flatMap((s,i)=>s.result?.type==='draw'&&s.position.turn===turn?[i]:[]).slice(0,4);assert.equal(ids.length,4);for(const index of ids){const s=g.states[index];assert.deepEqual(r.getResult(s.position),s.result);assert.deepEqual(f.getResult(s.position),s.result);controls.push({index,position:s.position,result:s.result});}}
const hashes={};for(const p of [source,'research/competitive-engine-v1/three-piece-search-plan-2026-10-28.md','src/bot.js','src/search.js','src/rules.js'])hashes[p]=createHash('sha256').update(await readFile(p)).digest('hex');const summary={queries:rows.length,terminalControls:controls.length,winningRoots:rows.filter(x=>x.winner===x.position.turn).length,outcomeChanged:rows.filter(x=>x.outcomeChanged).map(x=>x.index),nodes:rows.reduce((n,x)=>n+x.search.nodes,0),meanDepth:rows.reduce((n,x)=>n+x.search.completedDepth,0)/rows.length};await writeFile('research/competitive-engine-v1/three-piece-search-comparison.json',JSON.stringify({purpose:'One preregistered32root100ms comparison plus8 terminal controls. Freshhistory only; synthetic outcomes not game wins or strength. Rank/shorter-mate changes in losing roots are not saves. No reruns or candidate.',options,hashes,script:await readFile(new URL(import.meta.url),'utf8'),strata,selected,rows,controls,summary},null,2)+'\n');console.log(JSON.stringify(summary));
